export function getRescueInstruction<
  TAccountOwner extends string,
  TAccountPosition extends string,
  TAccountCollateralMint extends string,
  TAccountDestinationMint extends string,
  TAccountBorrowMint extends string,
  TAccountPositionCollateralAccount extends string,
  TAccountPositionUsdcAccount extends string,
  TAccountPositionDestinationAccount extends string,
  TAccountOwnerCollateralAccount extends string,
  TAccountOwnerUsdcAccount extends string,
  TAccountOwnerDestinationAccount extends string,
  TAccountObligation extends string,
  TAccountLendingMarket extends string,
  TAccountLendingMarketAuthority extends string,
  TAccountCollateralReserve extends string,
  TAccountCollateralReserveCollateralSupply extends string,
  TAccountCollateralReserveCollateralMint extends string,
  TAccountCollateralReserveLiquiditySupply extends string,
  TAccountCollateralReserveFarmState extends string,
  TAccountCollateralObligationFarmState extends string,
  TAccountBorrowReserve extends string,
  TAccountScopePrices extends string,
  TAccountBorrowScopePrices extends string,
  TAccountFarmsProgram extends string,
  TAccountKaminoProgram extends string,
  TAccountInstructionSysvar extends string,
  TAccountKaminoCollateralTokenProgram extends string,
  TAccountCollateralTokenProgram extends string,
  TAccountBorrowTokenProgram extends string,
  TAccountDestinationTokenProgram extends string,
  TProgramAddress extends Address = typeof ACCRUE_PROGRAM_ADDRESS,
>(
  input: RescueInput<
    TAccountOwner,
    TAccountPosition,
    TAccountCollateralMint,
    TAccountDestinationMint,
    TAccountBorrowMint,
    TAccountPositionCollateralAccount,
    TAccountPositionUsdcAccount,
    TAccountPositionDestinationAccount,
    TAccountOwnerCollateralAccount,
    TAccountOwnerUsdcAccount,
    TAccountOwnerDestinationAccount,
    TAccountObligation,
    TAccountLendingMarket,
    TAccountLendingMarketAuthority,
    TAccountCollateralReserve,
    TAccountCollateralReserveCollateralSupply,
    TAccountCollateralReserveCollateralMint,
    TAccountCollateralReserveLiquiditySupply,
    TAccountCollateralReserveFarmState,
    TAccountCollateralObligationFarmState,
    TAccountBorrowReserve,
    TAccountScopePrices,
    TAccountBorrowScopePrices,
    TAccountFarmsProgram,
    TAccountKaminoProgram,
    TAccountInstructionSysvar,
    TAccountKaminoCollateralTokenProgram,
    TAccountCollateralTokenProgram,
    TAccountBorrowTokenProgram,
    TAccountDestinationTokenProgram
  >,
  config?: { programAddress?: TProgramAddress },
): RescueInstruction<
  TProgramAddress,
  TAccountOwner,
  TAccountPosition,
  TAccountCollateralMint,
  TAccountDestinationMint,
  TAccountBorrowMint,
  TAccountPositionCollateralAccount,
  TAccountPositionUsdcAccount,
  TAccountPositionDestinationAccount,
  TAccountOwnerCollateralAccount,
  TAccountOwnerUsdcAccount,
  TAccountOwnerDestinationAccount,
  TAccountObligation,
  TAccountLendingMarket,
  TAccountLendingMarketAuthority,
  TAccountCollateralReserve,
  TAccountCollateralReserveCollateralSupply,
  TAccountCollateralReserveCollateralMint,
  TAccountCollateralReserveLiquiditySupply,
  TAccountCollateralReserveFarmState,
  TAccountCollateralObligationFarmState,
  TAccountBorrowReserve,
  TAccountScopePrices,
  TAccountBorrowScopePrices,
  TAccountFarmsProgram,
  TAccountKaminoProgram,
  TAccountInstructionSysvar,
  TAccountKaminoCollateralTokenProgram,
  TAccountCollateralTokenProgram,
  TAccountBorrowTokenProgram,
  TAccountDestinationTokenProgram
> {
  // Program address.
  const programAddress = config?.programAddress ?? ACCRUE_PROGRAM_ADDRESS;

  // Original accounts.
  const originalAccounts = {
    owner: { value: input.owner ?? null, isWritable: true },
    position: { value: input.position ?? null, isWritable: true },
    collateralMint: { value: input.collateralMint ?? null, isWritable: false },
    destinationMint: {
      value: input.destinationMint ?? null,
      isWritable: false,
    },
    borrowMint: { value: input.borrowMint ?? null, isWritable: false },
    positionCollateralAccount: {
      value: input.positionCollateralAccount ?? null,
      isWritable: true,
    },
    positionUsdcAccount: {
      value: input.positionUsdcAccount ?? null,
      isWritable: true,
    },
    positionDestinationAccount: {
      value: input.positionDestinationAccount ?? null,
      isWritable: true,
    },
    ownerCollateralAccount: {
      value: input.ownerCollateralAccount ?? null,
      isWritable: true,
    },
    ownerUsdcAccount: {
      value: input.ownerUsdcAccount ?? null,
      isWritable: true,
    },
    ownerDestinationAccount: {
      value: input.ownerDestinationAccount ?? null,
      isWritable: true,
    },
    obligation: { value: input.obligation ?? null, isWritable: true },
    lendingMarket: { value: input.lendingMarket ?? null, isWritable: true },
    lendingMarketAuthority: {
      value: input.lendingMarketAuthority ?? null,
      isWritable: false,
    },
    collateralReserve: {
      value: input.collateralReserve ?? null,
      isWritable: true,
    },
    collateralReserveCollateralSupply: {
      value: input.collateralReserveCollateralSupply ?? null,
      isWritable: true,
    },
    collateralReserveCollateralMint: {
      value: input.collateralReserveCollateralMint ?? null,
      isWritable: true,
    },
    collateralReserveLiquiditySupply: {
      value: input.collateralReserveLiquiditySupply ?? null,
      isWritable: true,
    },
    collateralReserveFarmState: {
      value: input.collateralReserveFarmState ?? null,
      isWritable: true,
    },
    collateralObligationFarmState: {
      value: input.collateralObligationFarmState ?? null,
      isWritable: true,
    },
    borrowReserve: { value: input.borrowReserve ?? null, isWritable: true },
    scopePrices: { value: input.scopePrices ?? null, isWritable: false },
    borrowScopePrices: {
      value: input.borrowScopePrices ?? null,
      isWritable: false,
    },
    farmsProgram: { value: input.farmsProgram ?? null, isWritable: false },
    kaminoProgram: { value: input.kaminoProgram ?? null, isWritable: false },
    instructionSysvar: {
      value: input.instructionSysvar ?? null,
      isWritable: false,
    },
    kaminoCollateralTokenProgram: {
      value: input.kaminoCollateralTokenProgram ?? null,
      isWritable: false,
    },
    collateralTokenProgram: {
      value: input.collateralTokenProgram ?? null,
      isWritable: false,
    },
    borrowTokenProgram: {
      value: input.borrowTokenProgram ?? null,
      isWritable: false,
    },
    destinationTokenProgram: {
      value: input.destinationTokenProgram ?? null,
      isWritable: false,
    },
  };
  const accounts = originalAccounts as Record<
    keyof typeof originalAccounts,
    ResolvedAccount
  >;

  // Resolve default values.
  if (!accounts.farmsProgram.value) {
    accounts.farmsProgram.value =
      (KAMINO_FARMS_PROGRAM_ADDRESS as Address<"FarmsPZpWu9i7Kky8tPN37rs2TpmMrAZrC7S7vJa91Hr">);
  }
  if (!accounts.kaminoProgram.value) {
    accounts.kaminoProgram.value =
      (KAMINO_LENDING_PROGRAM_ADDRESS as Address<"KLend2g3cP87fffoy8q1mQqGKjrxjC8boSyAYavgmjD">);
  }
  if (!accounts.instructionSysvar.value) {
    accounts.instructionSysvar.value =
      "Sysvar1nstructions1111111111111111111111111" as Address<"Sysvar1nstructions1111111111111111111111111">;
  }
  if (!accounts.kaminoCollateralTokenProgram.value) {
    accounts.kaminoCollateralTokenProgram.value =
      "TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA" as Address<"TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA">;
  }

  const getAccountMeta = getAccountMetaFactory(programAddress, "programId");
  return Object.freeze({
    accounts: [
      getAccountMeta(accounts.owner),
      getAccountMeta(accounts.position),
      getAccountMeta(accounts.collateralMint),
      getAccountMeta(accounts.destinationMint),
      getAccountMeta(accounts.borrowMint),
      getAccountMeta(accounts.positionCollateralAccount),
      getAccountMeta(accounts.positionUsdcAccount),
      getAccountMeta(accounts.positionDestinationAccount),
      getAccountMeta(accounts.ownerCollateralAccount),
      getAccountMeta(accounts.ownerUsdcAccount),
      getAccountMeta(accounts.ownerDestinationAccount),
      getAccountMeta(accounts.obligation),
      getAccountMeta(accounts.lendingMarket),
      getAccountMeta(accounts.lendingMarketAuthority),
      getAccountMeta(accounts.collateralReserve),
      getAccountMeta(accounts.collateralReserveCollateralSupply),
      getAccountMeta(accounts.collateralReserveCollateralMint),
      getAccountMeta(accounts.collateralReserveLiquiditySupply),
      getAccountMeta(accounts.collateralReserveFarmState),
      getAccountMeta(accounts.collateralObligationFarmState),
      getAccountMeta(accounts.borrowReserve),
      getAccountMeta(accounts.scopePrices),
      getAccountMeta(accounts.borrowScopePrices),
      getAccountMeta(accounts.farmsProgram),
      getAccountMeta(accounts.kaminoProgram),
      getAccountMeta(accounts.instructionSysvar),
      getAccountMeta(accounts.kaminoCollateralTokenProgram),
      getAccountMeta(accounts.collateralTokenProgram),
      getAccountMeta(accounts.borrowTokenProgram),
      getAccountMeta(accounts.destinationTokenProgram),
    ],
    data: getRescueInstructionDataEncoder().encode({}),
    programAddress,
  } as RescueInstruction<
    TProgramAddress,
    TAccountOwner,
    TAccountPosition,
    TAccountCollateralMint,
    TAccountDestinationMint,
    TAccountBorrowMint,
    TAccountPositionCollateralAccount,
    TAccountPositionUsdcAccount,
    TAccountPositionDestinationAccount,
    TAccountOwnerCollateralAccount,
    TAccountOwnerUsdcAccount,
    TAccountOwnerDestinationAccount,
    TAccountObligation,
    TAccountLendingMarket,
    TAccountLendingMarketAuthority,
    TAccountCollateralReserve,
    TAccountCollateralReserveCollateralSupply,
    TAccountCollateralReserveCollateralMint,
    TAccountCollateralReserveLiquiditySupply,
    TAccountCollateralReserveFarmState,
    TAccountCollateralObligationFarmState,
    TAccountBorrowReserve,
    TAccountScopePrices,
    TAccountBorrowScopePrices,
    TAccountFarmsProgram,
    TAccountKaminoProgram,
    TAccountInstructionSysvar,
    TAccountKaminoCollateralTokenProgram,
    TAccountCollateralTokenProgram,
    TAccountBorrowTokenProgram,
    TAccountDestinationTokenProgram
  >);
}

export type ParsedRescueInstruction<
  TProgram extends string = typeof ACCRUE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    owner: TAccountMetas[0];
    position: TAccountMetas[1];
    collateralMint: TAccountMetas[2];
    destinationMint: TAccountMetas[3];
    borrowMint: TAccountMetas[4];
    positionCollateralAccount: TAccountMetas[5];
    positionUsdcAccount: TAccountMetas[6];
    positionDestinationAccount: TAccountMetas[7];
    ownerCollateralAccount: TAccountMetas[8];
    ownerUsdcAccount: TAccountMetas[9];
    ownerDestinationAccount: TAccountMetas[10];
    obligation: TAccountMetas[11];
    lendingMarket: TAccountMetas[12];
    lendingMarketAuthority: TAccountMetas[13];
    collateralReserve: TAccountMetas[14];
    collateralReserveCollateralSupply: TAccountMetas[15];
    collateralReserveCollateralMint: TAccountMetas[16];
    collateralReserveLiquiditySupply: TAccountMetas[17];
    collateralReserveFarmState?: TAccountMetas[18] | undefined;
    collateralObligationFarmState?: TAccountMetas[19] | undefined;
    borrowReserve: TAccountMetas[20];
    scopePrices: TAccountMetas[21];
    borrowScopePrices: TAccountMetas[22];
    farmsProgram: TAccountMetas[23];
    kaminoProgram: TAccountMetas[24];
    instructionSysvar: TAccountMetas[25];
    kaminoCollateralTokenProgram: TAccountMetas[26];
    collateralTokenProgram: TAccountMetas[27];
    borrowTokenProgram: TAccountMetas[28];
    destinationTokenProgram: TAccountMetas[29];
  };
  data: RescueInstructionData;
};

export function parseRescueInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRescueInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 30) {
    // TODO: Coded error.
    throw new Error("Not enough accounts");
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === ACCRUE_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      owner: getNextAccount(),
      position: getNextAccount(),
      collateralMint: getNextAccount(),
      destinationMint: getNextAccount(),
      borrowMint: getNextAccount(),
      positionCollateralAccount: getNextAccount(),
      positionUsdcAccount: getNextAccount(),
      positionDestinationAccount: getNextAccount(),
      ownerCollateralAccount: getNextAccount(),
      ownerUsdcAccount: getNextAccount(),
      ownerDestinationAccount: getNextAccount(),
      obligation: getNextAccount(),
      lendingMarket: getNextAccount(),
      lendingMarketAuthority: getNextAccount(),
      collateralReserve: getNextAccount(),
      collateralReserveCollateralSupply: getNextAccount(),
      collateralReserveCollateralMint: getNextAccount(),
      collateralReserveLiquiditySupply: getNextAccount(),
      collateralReserveFarmState: getNextOptionalAccount(),
      collateralObligationFarmState: getNextOptionalAccount(),
      borrowReserve: getNextAccount(),
      scopePrices: getNextAccount(),
      borrowScopePrices: getNextAccount(),
      farmsProgram: getNextAccount(),
      kaminoProgram: getNextAccount(),
      instructionSysvar: getNextAccount(),
      kaminoCollateralTokenProgram: getNextAccount(),
      collateralTokenProgram: getNextAccount(),
      borrowTokenProgram: getNextAccount(),
      destinationTokenProgram: getNextAccount(),
    },
    data: getRescueInstructionDataDecoder().decode(instruction.data),
  };
}
